    if ((mill.food_wheat || 0) >= 1) {
      consumeInventoryIdentity(world, storage.mill, "food_wheat", 1);
      createInventoryItem(world, storage.mill, "food_flour");
      produced = true;
      world.emit?.("town:produced", { chain: "mill", itemId: "food_flour" });
    }
  }

