        throw new Error("ItemInfo.validate(): weaponVfxProfile must be null, string, or object");
      if (typeof rec.weaponFamily !== "string")
        throw new Error("ItemInfo.validate(): weaponFamily must be a string");
      return true;
    },
  }
);

